import json
import requests

from taf.rfrl.procedures.resources.python.wft.configuration import ModelConfig
from taf.rfrl.procedures.resources.python.wft.exceptions import WFTError


class BuildEndpoint(object):
    """ Class representation of build endpoint of WFT Web API. """

    def __init__(self, project, component, version):
        self._project = project
        self._component = component
        self._version = version
        self.config = ModelConfig()
        self._url = "{}/{}/{}/builds/{}.json".format(
            self.config.wft_api_address, project, component, version
        )

    def sub_builds(self):
        """
        Gets sub builds from WFT Web API

        :return: list of sub builds with details
            E.g. output::
            [{
              "id": 4342267,
              "sc": "NIDD_EQM",
              "title": "NIDD_EQM",
              "component": "NIDD_EQM",
              "project": "Common",
              "version": "EQM20B_2010_001_00"
            },
            {
              "id": 4342270,
              "sc": "NIDD_EQM_R",
              "title": "NIDD_EQM_R",
              "component": "NIDD_EQM_R",
              "project": "Common",
              "version": "EQMR20B_2010_001_00"
            }]
        :rtype: list of dicts
        """
        self._url = "{}?items[]=sub_builds&access_key={}".format(
            self._url, self.config.access_key
        )
        return json.loads(self._request(params="sub_builds"))["sub_builds"]

    def build_attributes(self):
        """
        Gets build attributes from WFT Web API

        :return: dict of build attributes
        :rtype: dict
        """
        self._url = "{}?items[]=sub_builds&access_key={}".format(
            self._url, self.config.access_key
        )
        return json.loads(self._request(params="build_attributes"))

    def get_baseline_sw_build(self):
        """
        Gets baseline SW build, using the knifeID to filter the knife table and match it with correct SW build
        :return: baseline SW build
        :rtype: str
        """
        knife_id = self._version.split("_")[-1]
        self._url = "{}/knife_request.json?access_key={}&view[items]=20&view[sorting_field]=id&" \
                    "view[sorting_direction]=DESC&view[columns][][id]=state&view[columns][][id]=created_at&" \
                    "view[columns][][id]=id&view[columns][][id]=baseline&" \
                    "view[view_filters_attributes][912260769182563][column]=id&" \
                    "view[view_filters_attributes][912260769182563][operation]=eq&" \
                    "view[view_filters_attributes][912260769182563][value][]={}".format(
                        self.config.wft_api_address, self.config.access_key, knife_id
                    )

        return json.loads(self._request(params="get_baseline_sw_build"))["items"][0]["baseline"]

    def get_specific_query(self, query):
        """
        Send query to WFT Web API and return the first 100 rows sorted by creation date (descending).
        Sending query to WFT you can get the information as from WFT GUI.
        However, please note that the query is limited to the project and component specified when
        creating the class object (BuildEndpoint).

        E.g.
            For class object BuildEndpoint created with parameters:
                BuildEndpoint(project='SBTS', component='CI_ENB', version='')
            you can create a query to receive information about software component CI_ENB from project SBTS

        :param query:
            E.g. input:
                f'&view[columns[][id]]=deliverer.project.full_path' \
                f'&view[columns[][id]]=deliverer.title' \
                f'&view[columns[][id]]=version' \
                f'&view[columns[][id]]=branch.title' \
                f'&view[columns[][id]]=promotion_status'
        :type query: str

        :return: list of rows fits to query
            E.g. output::
            [
                {
                    "deliverer.project.full_path":"SBTS",
                    "deliverer.title":"CI_ENB",
                    "version":"SBTS00_ENB_9999_240111_000025",
                    "branch.title":"SBTS00",
                    "promotion_status":false},
                {
                    "deliverer.project.full_path":"SBTS",
                    "deliverer.title":"CI_ENB",
                    "version":"SBTS00_ENB_9000_231221_000009",
                    "branch.title":"SBTS_PSINT",
                    "promotion_status":false}
                {...}
                ...
                {...}
            ]
        :rtype: list of dicts
        """
        _url_query = f'{self.config.wft_api_search_address}/build.json?access_key=' \
                     f'{self.config.access_key}' \
                     f'&view[items]=100' \
                     f'&view[sorting_field]=created_at' \
                     f'&view[sorting_direction]=DESC' \
                     f'{query}' \
                     f'&view[view_filters_attributes[1]][column]=component' \
                     f'&view[view_filters_attributes[1]][operation]=eq' \
                     f'&view[view_filters_attributes[1]][value][]={self._component}&'
        resp = requests.get(_url_query)
        self._check_response(resp)
        resp_cont = resp.content
        items = json.loads(resp_cont)['items']
        return items

    def build_storages(self):
        """
        Gets build storages from WFT Web API

        :return: dict of build storage
        :rtype: dict
        """
        self._url = f"{self.config.wft_api_address}/{self._project}/{self._component}/builds/{self._version}/storages/results.json"
        params = {"access_key": self.config.access_key, "force": "true"}
        return json.loads(self._request(params))

    @staticmethod
    def _check_response(response):
        if not response.ok:
            msg = (
                "endpoint returned bad response: "
                '"({response.status_code}) {response.reason} {response.content}".'
            )
            msg = msg.format(response=response)
            raise WFTError(msg)

    def _request(self, params):
        response = requests.get(self._url, params=params)
        self._check_response(response)
        return response.content

    @classmethod
    def custom_request(cls, query):
        conf = ModelConfig()
        response = requests.get(f"{conf.wft_api_address}/build.json?access_key={conf.access_key}&{query}")
        cls._check_response(response)
        return json.loads(response.content)
